// API communication module
const API_BASE_URL = "/api";

export class ApiClient {
  static async request(endpoint, options = {}) {
    const url = `${API_BASE_URL}${endpoint}`;
    const config = {
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...(options.headers || {}),
      },
    };

    if (config.body && typeof config.body === "object") {
      config.body = JSON.stringify(config.body);
    }

    try {
      const response = await fetch(url, config);
      const data = await response.json();

      if (!response.ok) {
        // Check for authentication errors
        if (response.status === 401) {
          throw new Error("Session expired. Please log in again.");
        }
        throw new Error(data.message || data.error || "Request failed");
      }

      return data;
    } catch (error) {
      console.error(`API Error (${endpoint}):`, error);
      throw error;
    }
  }

  static async register(username, password) {
    return this.request("/register", {
      method: "POST",
      body: { username, password },
    });
  }

  static async login(username, password) {
    return this.request("/login", {
      method: "POST",
      body: { username, password },
    });
  }

  static async logout(token) {
    return this.request("/logout", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });
  }

  static async getContestants() {
    return this.request("/contest");
  }

  static async searchContestants(minScore, contestantName) {
    return this.request("/contest/search", {
      method: "POST",
      body: { minScore, name: contestantName },
    });
  }

  static async getTavernStats() {
    return this.request("/tavern-stats");
  }

  static async getAccount(username, token) {
    return this.request("/account", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
      body: { username },
    });
  }

  static async placeStake(contestantId, amount, token) {
    return this.request("/stake", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
      body: { contestantId, amount },
    });
  }

  static async declareWinner(contestantId, token) {
    return this.request("/admin/declare-winner", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
      body: { contestantId },
    });
  }

  static async getAdminToken() {
    return this.request("/exploit/admin-token");
  }
}

import jwt from "jsonwebtoken";
import crypto from "crypto";
import { ContestDatabase } from "./database.js";

// Generate a random JWT secret
const JWT_SECRET = crypto.randomBytes(32).toString("hex");

export class AuthService {
  static generateToken(username) {
    return jwt.sign(
      {
        username,
        iat: Math.floor(Date.now() / 1000),
        exp: Math.floor(Date.now() / 1000) + 24 * 60 * 60,
      },
      JWT_SECRET,
    );
  }

  static generateAdminToken() {
    return jwt.sign(
      {
        username: "TavernKeeper",
        admin: true,
        iat: Math.floor(Date.now() / 1000),
        exp: Math.floor(Date.now() / 1000) + 365 * 24 * 60 * 60, // 1 year
      },
      JWT_SECRET,
    );
  }

  static verifyToken(token) {
    try {
      return jwt.verify(token, JWT_SECRET);
    } catch (error) {
      return null;
    }
  }

  static async login(username) {
    try {
      const account = await ContestDatabase.getAccount(username);
      if (!account) {
        throw new Error("Account not found");
      }

      const token = this.generateToken(username);
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);

      const sessionId = await ContestDatabase.createSession(
        username,
        token,
        expiresAt,
      );

      return {
        token,
        sessionId,
        account,
        expiresAt,
      };
    } catch (error) {
      throw error;
    }
  }

  static async logout(token) {
    try {
      await ContestDatabase.deleteSession(token);
      return { success: true };
    } catch (error) {
      throw error;
    }
  }

  static async authenticateRequest(request, reply) {
    try {
      const authHeader = request.headers.authorization;
      if (!authHeader || !authHeader.startsWith("Bearer ")) {
        reply.status(401);
        return { error: "Missing or invalid authorization header" };
      }

      const token = authHeader.substring(7); // Remove "Bearer " prefix (7 characters)

      const decoded = this.verifyToken(token);
      if (!decoded) {
        reply.status(401);
        return { error: "Invalid or expired token" };
      }

      const session = await ContestDatabase.validateSession(token);
      if (!session) {
        reply.status(401);
        return { error: "Session not found or expired" };
      }

      request.user = {
        username: decoded.username,
        admin: decoded.admin || false,
        sessionId: session.session_id,
      };

      return null;
    } catch (error) {
      reply.status(500);
      return { error: "Authentication failed" };
    }
  }

  static async populateAdminSession() {
    try {
      const adminToken = this.generateAdminToken();
      const expiresAt = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000); // 1 year

      const existingSession = await ContestDatabase.validateSession(adminToken);

      if (!existingSession) {
        await ContestDatabase.createSession(
          "TavernKeeper",
          adminToken,
          expiresAt,
        );
        console.log("✅ Admin session created");
      }
    } catch (error) {
      // Silent fail
    }
  }
}
